// test_modules/qa/qa_new_tests256.rs::q256_maki_reveal_crossroads_replacement
static void gen_q256_maki_reveal_crossroads_replacement(void){
    // 
    // db loaded via rb_load
    TestGame tg; test_game_new(&tg);
    // 
    int maki = test_id(&tg, "PL!-sd1-006-SD");
    int crossroads = test_id(&tg, "PL!-bp6-024-L");
    int muse_live = test_id(&tg, "PL!-bp3-019-L");
    int filler_live = test_id(&tg, "PL!SP-sd1-023-SD");
    // 
    // // Put Maki in hand, 錯覚CROSSROADS in hand (to reveal), a μ's live in waitroom
    test_add_to_hand(&tg, maki);
    test_add_to_hand(&tg, crossroads);
    // TODO: game.add_to_discard(muse_live);
    // 
    // // Put a filler card in success zone (will be returned to hand by step a)
    // TODO: game.state
    // TODO: .player1
    // TODO: .success_live_card_zone
    // TODO: .cards
    // TODO: .push(filler_live);
    // // ... add filler_live to hand for the "returned to hand" check
    test_add_to_hand(&tg, filler_live);
    // 
    // // Give energy to play Maki (cost 9)
    test_give_energy(&tg, 9);
    // 
    // // Play Maki to stage → debut triggers
    test_play_to_stage(&tg, maki, 1);
    // 
    // // Step 1: Optional reveal cost — observed: SelectCard zone=hand
    // // count=1 allow_skip=true; crossroads is at hand index 0.
    test_has_pending_choice(&tg);
    // TODO assert_eq (unresolved): assert_eq!( game.pending_choice_type().as_deref(), Some("SelectCard"), "expected SelectCard reveal-cost prompt" );
    rb_resume_with_choice(&tg.state, 0);
    // 
    // // Effect step a returns the success-zone card to hand AUTOMATICALLY
    // // (single candidate, can_skip=false -> no prompt), so the next thing
    // // pending is already the step-b replacement choice.
    // // Observed: SelectCard zone=discard count=1 allow_skip=true
    // // group=μ's live_card — "Choose a live card from discard to place in
    // // your success zone (or skip to place the original card)".
    test_has_pending_choice(&tg);
    // TODO assert_eq (unresolved): assert_eq!( game.pending_choice_type().as_deref(), Some("SelectCard"), "expected SelectCard replacement prompt" );
    rb_resume_with_choice(&tg.state, 0);
    // 
    // // Ability fully resolved after the replacement pick.
    test_has_pending_choice(&tg);
    // 
    // // Verifications:
    // // 1. 錯覚CROSSROADS should be in waitroom (replaced from success zone placement)
    CHECK(test_zone_has_id(&tg, 0, "discard", crossroads), "q256_maki_reveal_crossroads_replacement");
    // 
    // // 2. The μ's live card should be in success zone
    // TODO assert: assert!( game.state .player1 .success_live_card_zone .cards .contains(&muse_live), "μ's live card should be in success zone (replacement target)" );
    // 
    // // 3. The filler live card that was in success zone should now be in hand
    CHECK(test_zone_has_id(&tg, 0, "hand", filler_live), "q256_maki_reveal_crossroads_replacement");
    // 
    // // 4. Maki should be on stage in Center
    CHECK_EQ(tg.state.p[0].stage[1], maki, "q256_maki_reveal_crossroads_replacement");
    // 
}

