// test_modules/abilities/moderate/love_u_test.rs::love_u_q192_live_success_all_blade_score_up
static void gen_love_u_q192_live_success_all_blade_score_up(void){
    // 
    // db loaded via rb_load
    TestGame tg; test_game_new(&tg);
    // 
    int love_u = test_id(&tg, "PL!N-bp3-030-L");
    int filler = test_id(&tg, "PL!-sd1-010-SD");
    int aqours_member = test_id(&tg, "PL!S-sd1-003-SD");
    int yell_h06 = test_id(&tg, "PL!-sd1-002-SD");
    int b_all_card = test_id(&tg, "PL!-sd1-020-SD");
    // 
    // // One member on stage (so live can succeed)
    tg.state.p[0].stage[0] = aqours_member;
    tg.state.p[0].stage[1] = -1;
    tg.state.p[0].stage[2] = -1;
    test_add_to_hand(&tg, love_u);
    // 
    // // Phase transitions before yell (Pass 4 in Draw phase draws 1 card from
    // // top of deck index 0).  Yell draws from remaining top 3 cards (blade=3).
    // // Push order: index 0 = drawn to hand, indices 1-3 = yell reveals.
    // // Stage hearts (aqours_member): heart02=1, heart04=2, heart05=1
    // // Yell must provide heart01, heart03, heart06 to meet Love U's need_heart.
    // // The b_all card provides a wildcard heart00 that can cover heart01.
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, yell_h06);
    test_add_to_deck(&tg, b_all_card);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    // 
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    // 
    // // inlined helper advance_to_live_card_set_p1
    // 
    rb_advance_phase(&tg.state);
    rb_advance_phase(&tg.state);
    rb_advance_phase(&tg.state);
    rb_advance_phase(&tg.state);
    rb_advance_phase(&tg.state);
    CHECK(strstr(rb_phase_name(tg.state.phase), "LiveCardSet") != NULL, "love_u_q192_live_success_all_blade_score_up");
    // 
    test_set_live_card(&tg, 0, love_u);
    // // inlined helper advance_to_live_success
    // 
    rb_advance_phase(&tg.state);
    rb_advance_phase(&tg.state);
    rb_advance_phase(&tg.state);
    rb_advance_phase(&tg.state);
    rb_advance_phase(&tg.state);
    // 
    // 
    // // LiveSuccess fires — condition evaluated. A b_all card was among yell-revealed
    // // cards, so has_all_blade condition should pass and score should be +1.
    // TODO assert: assert!( !game.state.player1.success_live_card_zone.cards.is_empty(), "Live card should have reached success_live_card_zone after LiveSuccess" );
    CHECK_EQ(rb_mods_get_score(&tg.state.mods, love_u), 0, "love_u_q192_live_success_all_blade_score_up");
    int l = 0;
    // TODO assert_eq (unresolved): assert_eq!(l.score - l.base_score, 1, "bonus in final score");
    // 
}

