// test_modules/abilities/simple/per_unit_discard_fix.rs::test_per_unit_discard_bug_fix
static void gen_test_per_unit_discard_bug_fix(void){
    // 
    // db loaded via rb_load
    TestGame tg; test_game_new(&tg);
    // 
    int filler = test_id(&tg, "PL!-sd1-010-SD");
    tg.state.p[0].stage[0] = filler;
    tg.state.p[0].stage[1] = filler;
    tg.state.p[0].stage[2] = -1;
    // clear
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    // 
    int discard_before = tg.state.p[0].discard.n;
    // 
    // // Draw phase — verify 1 card drawn, no unexpected discards
    // TODO: TurnEngine::advance_phase(&mut game.state);
    // 
    int discard_after = tg.state.p[0].discard.n;
    CHECK_EQ(discard_after, discard_before, "test_per_unit_discard_bug_fix");
    // 
}

