// test_modules/batches/untested_abilities_batch28_test.rs::pb1007_with_lilywhite_member_retrieves_mus_live
static void gen_pb1007_with_lilywhite_member_retrieves_mus_live(void){
    // 
    // db loaded via rb_load
    TestGame tg; test_game_new(&tg);
    int me = test_id(&tg, "PL!-pb1-007-R");
    int mate = test_id(&tg, "PL!-bp3-014-N");
    tg.state.p[0].stage[0] = me;
    tg.state.p[0].stage[1] = mate;
    test_give_energy(&tg, 15);
    // 
    // // Hand cost: discard 3 (reduced by success-zone cards, none staged here).
    int f1 = test_id(&tg, "PL!-sd1-010-SD");
    int f2 = test_id(&tg, "PL!-sd1-010-SD");
    int f3 = test_id(&tg, "PL!-sd1-010-SD");
    test_add_to_hand(&tg, f1);
    test_add_to_hand(&tg, f2);
    test_add_to_hand(&tg, f3);
    // 
    // // μ's live card sits in the waitroom for retrieval.
    int mus_live = test_id(&tg, "PL!-sd1-020-SD");
    test_add_to_discard(&tg, mus_live);
    // 
    test_activate_ability(&tg, me);
    test_has_pending_choice(&tg);
    // TODO assert_eq (unresolved): assert_eq!( game.pending_choice_type().as_deref(), Some("SelectCard"), "expected SelectCard for the 3-card hand cost" );
    rb_resume_with_choice(&tg.state, 0);
    rb_resume_with_choice(&tg.state, 1);
    rb_resume_with_choice(&tg.state, 2);
    // 
    CHECK(test_zone_has_id(&tg, 0, "hand", mus_live), "pb1007_with_lilywhite_member_retrieves_mus_live");
    // 
}

