// test_modules/edge_cases/s_pb1_006_yohane_edge_test.rs::yohane_opponent_discards_no_blade
static void gen_yohane_opponent_discards_no_blade(void){
    // 
    // db loaded via rb_load
    TestGame tg; test_game_new(&tg);
    int yohane = test_id(&tg, "PL!S-pb1-006-R");
    int live_hand = test_id(&tg, "PL!-sd1-019-SD");
    tg.state.p[0].stage[0] = yohane;
    tg.state.p[0].stage[1] = -1;
    tg.state.p[0].stage[2] = -1;
    test_add_to_hand(&tg, live_hand);
    // TODO: game.state.player2.hand.cards.push(test_id(&tg, "PL!-sd1-010-SD"));
    // TODO: game.state.player2.hand.cards.push(test_id(&tg, "PL!-sd1-010-SD"));
    test_give_energy(&tg, 15);
    test_activate_ability(&tg, yohane);
    // // Cost is reveal live from hand, but the pending we get is opponent discard
    // // (the reveal cost is auto-handled as part of cost payment)
    test_has_pending_choice(&tg);
    rb_resume_with_choice(&tg.state, 0);
    test_drain_auto_choices(&tg);
    CHECK_EQ(rb_mods_get_blade(&tg.state.mods, yohane), 0, "yohane_opponent_discards_no_blade");
    // 
}

