    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    // 
    int _hand_before = 0;
    int _deck_before = 0;
    // 
    // // Advance to live start
    // // inlined helper advance_to_live_card_set_p1
    // 
    CHECK_EQ_STR(rb_phase_name(tg.state.phase), "Main", "cheer_pipeline_draw_and_score_icons");
    rb_advance_phase(&tg.state);
    CHECK_EQ_STR(rb_phase_name(tg.state.phase), "Active", "cheer_pipeline_draw_and_score_icons");
    rb_advance_phase(&tg.state);
    CHECK_EQ_STR(rb_phase_name(tg.state.phase), "Energy", "cheer_pipeline_draw_and_score_icons");
    rb_advance_phase(&tg.state);
    CHECK_EQ_STR(rb_phase_name(tg.state.phase), "Draw", "cheer_pipeline_draw_and_score_icons");
    rb_advance_phase(&tg.state);
    CHECK_EQ_STR(rb_phase_name(tg.state.phase), "Main", "cheer_pipeline_draw_and_score_icons");
    rb_advance_phase(&tg.state);
    CHECK(strstr(rb_phase_name(tg.state.phase), "LiveCardSet") != NULL, "cheer_pipeline_draw_and_score_icons");
    // 
    test_set_live_card(&tg, 0, live_card);
    // // inlined helper advance_to_live_start
    // 
    rb_advance_phase(&tg.state);
    rb_advance_phase(&tg.state);
    // 
    // 
    // // Pass through both performance phases
    rb_advance_phase(&tg.state);
    rb_advance_phase(&tg.state);
    // 
    // // After FirstAttackerPerformance:
    // // 1. Yell drew 1 card (blade=1) to resolution zone → the b_all card
    // // 2. The b_all card's blade_heart={b_all:1} → wildcard heart00 added to owned hearts
    // // 3. The live card's special_heart={draw:1} → 1 card drawn to hand (filler)
    // // 4. cheer_icon_count includes the b_all icon (counted as icon)
    // // 5. The resolution zone cards were moved to waitroom after processing
    // 
    // // Hand: started with live_card (1), played it (-1), drew 1 from LiveCardSet (+1),
    // // drew from special_heart draw (+1). Also the yell cards went to waitroom, not hand.
    // // So hand_before = 1 (just live_card). After: -1+1+1 = 2
    int hand_after = 0;
    // TODO assert: assert!( hand_after >= 1, "Should have cards in hand after live performance" );
    // 
