    // 
    // // Stage covers heart01+heart03 (ことり fillers) and heart06 (絢瀬絵里) so
    // // START:DASH!! succeeds without any yell help.
    int kotori_a = test_id(&tg, "PL!-sd1-010-SD");
    int kotori_b = test_id(&tg, "PL!-sd1-010-SD");
    int eri = test_id(&tg, "PL!-sd1-002-SD");
