    test_add_to_stage(&tg, 1, kotori_b);
    test_add_to_stage(&tg, 1, eri);
    // 
    // // A second START:DASH!! copy goes ON TOP of the deck → revealed by yell.
    int dash_on_deck = test_id(&tg, "PL!-sd1-019-SD");
    int sacrificial_fill = test_id(&tg, "PL!-sd1-010-SD");
    // 
    int live_card = test_id(&tg, "PL!-sd1-019-SD");
    test_add_to_hand(&tg, live_card);
    // 
    // // inlined helper advance_to_live_card_set_p1
