    CHECK_EQ_STR(rb_phase_name(tg.state.phase), "Main", "cheer_pipeline_score_icon");
    rb_advance_phase(&tg.state);
    CHECK_EQ_STR(rb_phase_name(tg.state.phase), "Active", "cheer_pipeline_score_icon");
