    CHECK(strstr(rb_phase_name(tg.state.phase), "LiveCardSet") != NULL, "cheer_pipeline_score_icon");
    // 
    test_set_live_card(&tg, 0, live_card);
    // // Deck layout applied AFTER set_live_card (index 0 = top): position 0 is
