// test_modules/abilities/simple/duplicate_id_mulligan_test.rs::duplicate_cards_on_stage_have_unique_ids
static void gen_duplicate_cards_on_stage_have_unique_ids(void){
    // 
    // db loaded via rb_load
    TestGame tg; test_game_new(&tg);
    // 
    test_give_energy(&tg, 10);
    // 
    int card1 = test_id(&tg, "PL!-sd1-005-SD");
    int card2 = test_id(&tg, "PL!-sd1-005-SD");
    // 
    // TODO: assert_ne!(
    // TODO: card1, card2,
    // TODO: "Two copies of the same card must have unique IDs"
    // TODO: );
    // 
    test_add_to_hand(&tg, card1);
    test_add_to_hand(&tg, card2);
    // 
    test_play_to_stage(&tg, card1, 1);
    CHECK_EQ(tg.state.p[0].stage[1], card1, "duplicate_cards_on_stage_have_unique_ids");
    // 
    test_play_to_stage(&tg, card2, 2);
    CHECK_EQ(tg.state.p[0].stage[2], card2, "duplicate_cards_on_stage_have_unique_ids");
    // 
    // TODO: assert_ne!(
    // TODO: game.state.player1.stage.stage[1], game.state.player1.stage.stage[2],
    // TODO: "Center and right must have different card IDs"
    // TODO: );
    // 
    CHECK((!test_zone_has_id(&tg, 0, "discard", card1)), "duplicate_cards_on_stage_have_unique_ids");
    CHECK((!test_zone_has_id(&tg, 0, "discard", card2)), "duplicate_cards_on_stage_have_unique_ids");
    // 
}

