    rb_advance_phase(&tg.state);
    CHECK_EQ_STR(rb_phase_name(tg.state.phase), "Active", "kagayaiteru_live_success_draw_then_discard");
    rb_advance_phase(&tg.state);
    CHECK_EQ_STR(rb_phase_name(tg.state.phase), "Energy", "kagayaiteru_live_success_draw_then_discard");
    rb_advance_phase(&tg.state);
    CHECK_EQ_STR(rb_phase_name(tg.state.phase), "Draw", "kagayaiteru_live_success_draw_then_discard");
    rb_advance_phase(&tg.state);
    CHECK_EQ_STR(rb_phase_name(tg.state.phase), "Main", "kagayaiteru_live_success_draw_then_discard");
    rb_advance_phase(&tg.state);
    CHECK(strstr(rb_phase_name(tg.state.phase), "LiveCardSet") != NULL, "kagayaiteru_live_success_draw_then_discard");
    // 
