    test_has_pending_choice(&tg);
    // TODO assert_eq (unresolved): assert_eq!( game.pending_choice_type().as_deref(), Some("SelectCard"), "expected SelectCard for the discard" );
    rb_resume_with_choice(&tg.state, 0);
    // 
