// test_modules/abilities/simple/rin_test.rs::rin_q123_activate_empty_waitroom
static void gen_rin_q123_activate_empty_waitroom(void){
    // 
    // db loaded via rb_load
    TestGame tg; test_game_new(&tg);
    // 
    int rin = test_id(&tg, "PL!-sd1-005-SD");
    int filler = test_id(&tg, "PL!-sd1-010-SD");
    // 
    // // Stage: 星空凛 at center
    tg.state.p[0].stage[0] = -1;
    tg.state.p[0].stage[1] = rin;
    tg.state.p[0].stage[2] = -1;
    // 
    // // Hand: a card for hand count (not relevant here)
    test_add_to_hand(&tg, filler);
    // 
    // // No live cards in waitroom
    test_give_energy(&tg, 3);
    // 
    int stage_before = tg.state.p[0].stage[1];
    CHECK_EQ(stage_before, rin, "rin_q123_activate_empty_waitroom");
    // 
    test_activate_ability(&tg, rin);
    // 
    // // Self_cost moved Rin off stage → stage center should be empty
    CHECK_EQ(tg.state.p[0].stage[1], -1, "rin_q123_activate_empty_waitroom");
    // 
    // // Rin should be in waitroom
    CHECK(test_zone_has_id(&tg, 0, "discard", rin), "rin_q123_activate_empty_waitroom");
    // 
    // // No live card was recovered (waitroom had none), but ability succeeded
    // // The effect gracefully did nothing
    // 
}

