// test_modules/abilities/complex/sayaka_test.rs::sayaka_q63_ability_debut_no_cost_payment
static void gen_sayaka_q63_ability_debut_no_cost_payment(void){
    // 
    // db loaded via rb_load
    TestGame tg; test_game_new(&tg);
    // 
    int sayaka = test_id(&tg, "PL!HS-bp1-002-R");
    int hasuno_member = test_id(&tg, "PL!HS-bp2-004-R");
    // 
    // // Stage: 村野さやか in Center
    tg.state.p[0].stage[1] = sayaka;
    // 
    // // Hand: nothing needed
    // // Discard: a 蓮ノ空 member
    test_add_to_discard(&tg, hasuno_member);
    // 
    // // Energy: 2 for the activation cost
    test_give_energy(&tg, 2);
    // 
    test_activate_ability(&tg, sayaka);
    // 
    test_has_pending_choice(&tg);
    // TODO assert_eq (unresolved): assert_eq!( game.pending_choice_type().as_deref(), Some("SelectCard"), "expected SelectCard for the debut member pick (zone=discard)" );
    rb_resume_with_choice(&tg.state, 0);
    // 
    CHECK_EQ(tg.state.p[0].energy_active, 0, "sayaka_q63_ability_debut_no_cost_payment");
    CHECK(test_zone_has_id(&tg, 0, "discard", sayaka), "sayaka_q63_ability_debut_no_cost_payment");
    CHECK_EQ(tg.state.p[0].stage[1], hasuno_member, "sayaka_q63_ability_debut_no_cost_payment");
    // 
}

