// test_modules/abilities/moderate/kinako_bp5_test.rs::kinako_bp5_q234_deck_4_activation_succeeds_position_changes
static void gen_kinako_bp5_q234_deck_4_activation_succeeds_position_changes(void){
    // 
    // db loaded via rb_load
    TestGame tg; test_game_new(&tg);
    // 
    int kinako = test_id(&tg, "PL!SP-bp5-006-R");
    int filler = test_id(&tg, "PL!-sd1-010-SD");
    int center_member = test_id(&tg, "PL!-sd1-013-SD");
    // 
    // // Kinako at LeftSide, other member at Center
    tg.state.p[0].stage[0] = kinako;
    tg.state.p[0].stage[1] = center_member;
    tg.state.p[0].stage[2] = -1;
    // 
    // // 4 cards in deck (enough for cost of 3)
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    // 
    test_activate_ability(&tg, kinako);
    // 
    // // Cost: 3 cards discarded from deck
    CHECK_EQ(tg.state.p[0].deck.n, 1, "kinako_bp5_q234_deck_4_activation_succeeds_position_changes");
    // 
    // // Position change creates a choice (source_position unspecified → choose dest)
    test_has_pending_choice(&tg);
    // 
    // // Choose RightSide as destination
    rb_resume_with_choice(&tg.state, 2);
    // 
    // // Kinako moves from LeftSide(0) to empty RightSide(2)
    CHECK_EQ(tg.state.p[0].stage[0], -1, "kinako_bp5_q234_deck_4_activation_succeeds_position_changes");
    CHECK_EQ(tg.state.p[0].stage[2], kinako, "kinako_bp5_q234_deck_4_activation_succeeds_position_changes");
    CHECK_EQ(tg.state.p[0].stage[1], center_member, "kinako_bp5_q234_deck_4_activation_succeeds_position_changes");
    // 
}

// test_modules/abilities/moderate/kinako_bp5_test.rs::kinako_bp5_q104_deck_2_refresh_and_continue
static void gen_kinako_bp5_q104_deck_2_refresh_and_continue(void){
    // 
    // db loaded via rb_load
    TestGame tg; test_game_new(&tg);
    // 
    int kinako = test_id(&tg, "PL!SP-bp5-006-R");
    int filler = test_id(&tg, "PL!-sd1-010-SD");
    // 
    // // Kinako at LeftSide
    tg.state.p[0].stage[0] = kinako;
    tg.state.p[0].stage[1] = -1;
    tg.state.p[0].stage[2] = -1;
    // 
    // // 2 cards in deck (need 3), plus 3 cards already in waitroom
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_discard(&tg, filler);
    test_add_to_discard(&tg, filler);
    test_add_to_discard(&tg, filler);
    // 
    test_activate_ability(&tg, kinako);
    // 
    // // Q104: 2 taken from deck → refresh → 1 taken from new deck
    // // Waitroom should have 1 card (the 3rd one drawn from refreshed deck)
    // // The 2 original deck cards were discarded then reshuffled back → back in deck
    CHECK_EQ(tg.state.p[0].discard.n, 1, "kinako_bp5_q104_deck_2_refresh_and_continue");
    // // 2 original + 3 waitroom = 5 cards, took 3, so 2 remain in deck + 2 from
    // // original discarded and reshuffled = 4
    CHECK_EQ(tg.state.p[0].deck.n, 4, "kinako_bp5_q104_deck_2_refresh_and_continue");
    // 
    // // Position change choice should appear
    test_has_pending_choice(&tg);
    // // Complete the choice
    rb_resume_with_choice(&tg.state, 2);
    // 
    // // Kinako moved
    CHECK_EQ(tg.state.p[0].stage[0], -1, "kinako_bp5_q104_deck_2_refresh_and_continue");
    CHECK_EQ(tg.state.p[0].stage[2], kinako, "kinako_bp5_q104_deck_2_refresh_and_continue");
    // 
}

