// test_modules/abilities/simple/emma_bp5_test.rs::emma_bp5_q215_wait_energy_placed_then_activate
static void gen_emma_bp5_q215_wait_energy_placed_then_activate(void){
    // 
    // db loaded via rb_load
    TestGame tg; test_game_new(&tg);
    // 
    int emma = test_id(&tg, "PL!N-bp5-008-R");
    int filler = test_id(&tg, "PL!-sd1-010-SD");
    // 
    tg.state.p[0].stage[1] = emma;
    tg.state.p[0].stage[0] = filler;
    test_add_to_hand(&tg, filler);
    test_give_energy(&tg, 5);
    // 
    test_activate_ability(&tg, emma);
    // TODO: game.select_energy_from_zone(1); // place 1 energy under member
    // 
    // // Observed: after placing 1 energy under Emma, the "activate 2" effect
    // // resolves AUTOMATICALLY (ChangeState on active energies) — no further
    // // selection prompt appears.
    test_has_pending_choice(&tg);
    // 
    // // Cost correctly removes 1 from zone (under member). 4 remain.
    // // Activation effect then deactivates 2 → 2 remain.
    int ecount = tg.state.p[0].energy.n;
    int acount = tg.state.p[0].energy_active;
    // TODO: eprintln!("[EMMA] energy_zone cards={}, active={}", ecount, acount);
    // // Cost places 1 under member (4 remain). All 4 are already active, so
    // // the "activate 2" effect has no wait cards to activate. Card count is 4.
    CHECK_EQ(ecount, 4, "emma_bp5_q215_wait_energy_placed_then_activate");
    // 
}

