// test_modules/abilities/simple/nico_cannot_activate_test.rs::nico_blocks_kotori_activation
static void gen_nico_blocks_kotori_activation(void){
    // 
    // db loaded via rb_load
    TestGame tg; test_game_new(&tg);
    // 
    int filler = test_id(&tg, "PL!-sd1-010-SD");
    int nico = test_id(&tg, "PL!-pb1-009-R");
    int kotori = test_id(&tg, "PL!-pb1-012-R");
    // 
    // // Energy: filler(4) + nico(4) + kotori(2) = 10, give 15.
    test_give_energy(&tg, 15);
    // 
    // // ---- Step 1: Deploy Printemps filler ----
    test_add_to_hand(&tg, filler);
    test_play_to_stage(&tg, filler, 0);
    // TODO assert: assert!( game.state.mods.get_orientation_modifier(filler).is_none(), "Filler should start active (no modifier)" );
    // 
    // // Manually put filler in wait (Nico's ab#0 targets opponent stage).
    rb_mods_set_orientation(&tg.state.mods, filler, "wait");
    // TODO assert_eq (unresolved): assert_eq!( game.state.mods.get_orientation_modifier(filler), Some("wait"), "Filler should be in wait after manual setting" );
    // 
    // // ---- Step 2: Deploy Nico ----
    test_add_to_hand(&tg, nico);
    test_play_to_stage(&tg, nico, 1);
    test_drain_auto_choices(&tg);
    // 
    // // ab#0 fires but opponent stage is empty → no target → skips silently.
    // // ab#1 fires → cannot_activate_by_effect restriction is stored.
    // 
    // // Verify restriction is active.
    // TODO assert: assert!( game.state .cannot_activate_members .contains(&"p1".to_string()), "cannot_activate_members should contain player1's ID" );
    // 
    // // ---- Step 3: Deploy Kotori ----
    test_add_to_hand(&tg, kotori);
    test_play_to_stage(&tg, kotori, 2);
    // 
    // // Kotori ab#0: choice to activate up to 1 Printemps member.
    test_has_pending_choice(&tg);
    // // The filler (Printemps, in wait) is the only valid target.
    rb_resume_with_choice(&tg.state, 0);
    // 
    // // The cannot_activate_by_effect restriction should have blocked the
    // // state change. Filler should still be in wait.
    // TODO assert_eq (unresolved): assert_eq!( game.state.mods.get_orientation_modifier(filler), Some("wait"), "Filler should remain in wait — cannot_activate_by_effect blocked Kotori's activation" );
    // 
}

