    int filler_deck = test_id(&tg, "PL!-sd1-010-SD");
    // 
    // // Setup stage (Keke on Left)
    test_add_to_stage(&tg, 1, keke);
    // 
    // // Setup hand with 2 live cards to discard
    test_add_to_hand(&tg, live1);
    test_add_to_hand(&tg, live2);
