// test_modules/abilities/complex/nozomi_test.rs::nozomi_edge_equal_cost_baton_touch_no_trigger
static void gen_nozomi_edge_equal_cost_baton_touch_no_trigger(void){
    // 
    // db loaded via rb_load
    TestGame tg; test_game_new(&tg);
    // 
    int nozomi = test_id(&tg, "PL!-bp5-007-R");
    // // 東條希 costs 13. Use a cost-13 card on stage (any cost-13 member).
    int same_cost = test_id(&tg, "PL!SP-sd1-009-SD");
    int filler = test_id(&tg, "PL!-sd1-010-SD");
    // 
    test_add_to_hand(&tg, nozomi);
    test_add_to_hand(&tg, filler);
    test_add_to_hand(&tg, filler);
    test_add_to_hand(&tg, filler);
    test_give_energy(&tg, 13);
    // 
    // // Stage has a cost-13 card at Center
    tg.state.p[0].stage[1] = same_cost;
    test_play_to_stage(&tg, nozomi, 1);
    // 
    // // Baton touch occurs (equal cost → cost_paid = 13-13 = 0)
    // // But the ability's operator is "<" (replaced < new)
    // // 13 < 13 is false → condition should fail → no draw
    CHECK_EQ(tg.state.p[0].hand.n, 3, "nozomi_edge_equal_cost_baton_touch_no_trigger");
    // 
}

