// test_modules/abilities/moderate/wien_bp5_test.rs::wien_bp5_q223_p1_center_empty_opponent_chooses
static void gen_wien_bp5_q223_p1_center_empty_opponent_chooses(void){
    // 
    // db loaded via rb_load
    TestGame tg; test_game_new(&tg);
    // 
    int wien = test_id(&tg, "PL!SP-bp5-010-R");
    int p1_right = test_id(&tg, "PL!-sd1-010-SD");
    int p2_center = test_id(&tg, "PL!-sd1-013-SD");
    // 
    test_add_to_hand(&tg, wien);
    test_add_to_hand(&tg, p1_right);
    tg.state.p[0].stage[0] = -1;
    tg.state.p[0].stage[1] = -1;
    tg.state.p[0].stage[2] = p1_right;
    tg.state.p[1].stage[0] = -1;
    tg.state.p[1].stage[1] = p2_center;
    tg.state.p[1].stage[2] = -1;
    // 
    test_give_energy(&tg, 13);
    test_play_to_stage(&tg, wien, 0);
    // 
    // // P2 center has member → opponent's choice resolves first.
    // // Q223: opponent decides where their member goes.
    test_has_pending_choice(&tg);
    rb_resume_with_choice(&tg.state, 0);
    // 
    // // P2 center member moved to LeftSide
    CHECK_EQ(tg.state.p[1].stage[0], p2_center, "wien_bp5_q223_p1_center_empty_opponent_chooses");
    CHECK_EQ(tg.state.p[1].stage[1], -1, "wien_bp5_q223_p1_center_empty_opponent_chooses");
    // 
    // // P1 center was empty → no self-side choice
    test_has_pending_choice(&tg);
    // 
}

// test_modules/abilities/moderate/wien_bp5_test.rs::wien_bp5_q223_both_centers_occupied_both_choose
static void gen_wien_bp5_q223_both_centers_occupied_both_choose(void){
    // 
    // db loaded via rb_load
    TestGame tg; test_game_new(&tg);
    // 
    int wien = test_id(&tg, "PL!SP-bp5-010-R");
    int p1_center = test_id(&tg, "PL!-sd1-013-SD");
    int p1_right = test_id(&tg, "PL!-sd1-014-SD");
    int p2_center = test_id(&tg, "PL!-sd1-010-SD");
    // 
    test_add_to_hand(&tg, wien);
    test_add_to_hand(&tg, p1_right);
    tg.state.p[0].stage[0] = -1;
    tg.state.p[0].stage[1] = p1_center;
    tg.state.p[0].stage[2] = p1_right;
    // // P2: Center occupied, LeftSide+RightSide empty
    tg.state.p[1].stage[0] = -1;
    tg.state.p[1].stage[1] = p2_center;
    tg.state.p[1].stage[2] = -1;
    // 
    test_give_energy(&tg, 13);
    test_play_to_stage(&tg, wien, 0);
    // 
    // // Opponent's choice first
    test_has_pending_choice(&tg);
    rb_resume_with_choice(&tg.state, 0);
    // 
    CHECK_EQ(tg.state.p[1].stage[0], p2_center, "wien_bp5_q223_both_centers_occupied_both_choose");
    CHECK_EQ(tg.state.p[1].stage[1], -1, "wien_bp5_q223_both_centers_occupied_both_choose");
    // 
    // // Self's choice second (from pending_sequential_actions)
    test_has_pending_choice(&tg);
    rb_resume_with_choice(&tg.state, 2);
    // 
    // // P1 center moved to RightSide, p1_right swapped to Center
    CHECK_EQ(tg.state.p[0].stage[2], p1_center, "wien_bp5_q223_both_centers_occupied_both_choose");
    CHECK_EQ(tg.state.p[0].stage[1], p1_right, "wien_bp5_q223_both_centers_occupied_both_choose");
    CHECK_EQ(tg.state.p[0].stage[0], wien, "wien_bp5_q223_both_centers_occupied_both_choose");
    // 
}

