// test_modules/abilities/moderate/wien_pb2_test.rs::wien_q262_empty_hand_triggers_energy_move
static void gen_wien_q262_empty_hand_triggers_energy_move(void){
    // 
    // db loaded via rb_load
    TestGame tg; test_game_new(&tg);
    // 
    int wien = test_id(&tg, "PL!SP-pb2-010-R");
    int filler = test_id(&tg, "PL!-sd1-010-SD");
    int live_card = test_id(&tg, "PL!-sd1-020-SD");
    // 
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    // 
    // // Wien on center stage, give player energy on field
    tg.state.p[0].stage[1] = wien;
    test_give_energy(&tg, 5);
    // 
    // // Hand starts empty — no cards to discard
    // // Need a live card but hand is empty, so we add it temporarily
    test_add_to_hand(&tg, live_card);
    // 
    // // inlined helper advance_to_live_card_set_p1
    // 
    rb_advance_phase(&tg.state);
    rb_advance_phase(&tg.state);
    rb_advance_phase(&tg.state);
    rb_advance_phase(&tg.state);
    rb_advance_phase(&tg.state);
    CHECK(strstr(rb_phase_name(tg.state.phase), "LiveCardSet") != NULL, "wien_q262_empty_hand_triggers_energy_move");
    // 
    // 
    // // Hand should now have only the live card at this point
    // // Set it as the live card — after this hand is empty
    test_set_live_card(&tg, 0, live_card);
    // 
    int energy_zone_before = tg.state.p[0].energy_active;
    int energy_deck_before = 0;
    // 
    // // inlined helper advance_to_live_start
    // 
    rb_advance_phase(&tg.state);
    rb_advance_phase(&tg.state);
    // 
    // 
    // // Q262: Engine presents Skip/Pay choice for the optional discard.
    test_has_pending_choice(&tg);
    rb_resume_with_choice(&tg.state, 0);
    // 
    // // Q262: Energy zone→energy_deck movement auto-takes (fungible cards,
    // // no per-card selection needed after the optional discard skip).
    // 
    // // Q262: Energy card should have moved from energy zone to energy deck
    CHECK(tg.state.p[0].energy_active, "wien_q262_empty_hand_triggers_energy_move");
    // TODO assert: assert!( game.state.player1.energy_deck.cards.len() > energy_deck_before, "Q262: Energy deck should have gained a card" );
    // 
}

