// test_modules/abilities/simple/mia_test.rs::mia_q73_deck_has_live_card_after_refresh
static void gen_mia_q73_deck_has_live_card_after_refresh(void){
    // 
    // db loaded via rb_load
    TestGame tg; test_game_new(&tg);
    // 
    int mia = test_id(&tg, "PL!N-bp1-011-R");
    int filler = test_id(&tg, "PL!-sd1-010-SD");
    int live_card = test_id(&tg, "PL!-sd1-019-SD");
    // 
    // // Hand: ミア + filler to discard for optional cost + live card
    test_add_to_hand(&tg, mia);
    test_add_to_hand(&tg, filler);
    test_add_to_hand(&tg, live_card);
    // 
    // // Deck: all fillers, no live cards initially
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    // // Waitroom has the live card for refresh
    // TODO: game.add_to_discard(live_card);
    // 
    // // Give energy for ミア's cost (cost=9)
    test_give_energy(&tg, 10);
    // 
    // // Play ミア to stage center — triggers debut ability
    test_play_to_stage(&tg, mia, 1);
    // 
    // // Debut auto ability fires: optional cost (discard 1 from hand)
    test_has_pending_choice(&tg);
    // TODO assert_eq (unresolved): assert_eq!( game.pending_choice_type().as_deref(), Some("SelectCard"), "expected SelectCard for the discard cost" );
    rb_resume_with_choice(&tg.state, 0);
    // 
    // // Now reveal_until_live_card runs. Deck has 3 fillers, then refreshes from waitroom.
    // // The live card from waitroom gets revealed and goes to hand.
    CHECK(test_zone_has_id(&tg, 0, "hand", live_card), "mia_q73_deck_has_live_card_after_refresh");
    // 
}

