// test_modules/jidou/moderate/miyashita_ai_bp3_test.rs::ai_bp3_three_deploys_draws_to_five
static void gen_ai_bp3_three_deploys_draws_to_five(void){
    // 
    // db loaded via rb_load
    TestGame tg; test_game_new(&tg);
    // 
    int ai = 0;
    int filler = 0;
    int _hand_before = 0;
    int deck_before = 0;
    int discard_before = 0;
    // TODO destructuring: let (ai, filler, _hand_before, deck_before, discard_before) = setup_ai_bp3(&mut game, 3, 10);
    // 
    // // Deploy #1: filler to Left. debut_count becomes 1. Ai not on stage → no trigger.
    test_play_to_stage(&tg, filler, 0);
    // 
    // // Deploy #2: filler to Center. debut_count becomes 2. Ai not on stage → no trigger.
    test_play_to_stage(&tg, filler, 1);
    // 
    // // Deploy #3 (Ai) to Right. debut_count becomes 3. Ai is now on stage →
    // // auto-ability scanned → condition debut_count >= 3 passes →
    // // draw-until-count (target=5) fires.
    test_play_to_stage(&tg, ai, 2);
    // 
    // // After 3 deploys, hand went from 6 → 3 (3 cards used).
    // // draw-until-5: current=3, target=5, draws 2.
    CHECK_EQ(tg.state.p[0].hand.n, 5, "ai_bp3_three_deploys_draws_to_five");
    // TODO assert_eq (unresolved): assert_eq!( game.state.player1.main_deck.cards.len(), deck_before - 2, "Deck should lose 2 cards (drawn to reach 5)" );
    CHECK_EQ(tg.state.p[0].discard.n, discard_before, "ai_bp3_three_deploys_draws_to_five");
    CHECK_EQ(tg.state.p[0].stage[2], ai, "ai_bp3_three_deploys_draws_to_five");
    // 
}

