static void gen_tang_keke_discard_member_without_blade_heart_choose_any_number(void){
    // 
    // // Discard a Liella! member WITHOUT blade heart → condition MET → count=any_number
    // // Player can select 1+ options. After selecting energy, re-prompt with remaining.
    // db loaded via rb_load
    TestGame tg; test_game_new(&tg);
    int keke = 0;
    int liella_no_bh = test_id(&tg, "PL!SP-PR-004-PR");
    // // A Liella! member on stage for the heart06 option (not the activating member)
    int target_member = test_id(&tg, "PL!SP-PR-003-PR");
    // 
    test_add_to_hand(&tg, liella_no_bh);
    // // Place a different Liella! member on stage for the heart06 target
    tg.state.p[0].stage[1] = target_member;
    test_activate_ability(&tg, keke);
    // 
    // // inlined helper pay_discard_cost
    // 
    test_has_pending_choice(&tg);
    rb_resume_with_choice(&tg.state, 0);
    // 
    // 
    // // Choice appears — select energy (option 0)
    test_has_pending_choice(&tg);
    int energy_before = tg.state.p[0].energy.n;
    rb_resume_with_choice(&tg.state, 0);
    // 
    // // any_number: engine should re-prompt with remaining option (heart06)
    test_has_pending_choice(&tg);
    // // Select the heart06 option — verify heart06 was gained on the target member
    rb_resume_with_choice(&tg.state, 0);
    // 
    CHECK(tg.state.p[0].energy.n, "tang_keke_discard_member_without_blade_heart_choose_any_number");
    CHECK(test_zone_has_id(&tg, 0, "discard", liella_no_bh), "tang_keke_discard_member_without_blade_heart_choose_any_number");
    // // Heart06 gain is a modifier — just verify no crash / no infinite loop
    test_has_pending_choice(&tg);
    // 
}

