// test_modules/abilities/moderate/mari_test.rs::mari_q131_zero_deck_blocks_live_start
static void gen_mari_q131_zero_deck_blocks_live_start(void){
    // 
    // db loaded via rb_load
    TestGame tg; test_game_new(&tg);
    // 
    // // Give 2 cards: one consumed by set_live_card's replacement draw,
    // // leaving 1 — not enough for the 2-card look, but per Q85 we take
    // // what's available and let the player choose (or skip).
    int filler = test_id(&tg, "PL!-sd1-010-SD");
    // clear
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    tg.state.p[0].stage[0] = test_id(&tg, "PL!S-pb1-008-R");
    tg.state.p[0].stage[1] = filler;
    // 
    int live = test_id(&tg, "LL-bp5-001-L");
    test_add_to_hand(&tg, live);
    // 
    // // inlined helper advance_to_live_set
    // 
    rb_advance_phase(&tg.state);
    rb_advance_phase(&tg.state);
    rb_advance_phase(&tg.state);
    rb_advance_phase(&tg.state);
    rb_advance_phase(&tg.state);
    // 
    test_set_live_card(&tg, 0, live);
    rb_advance_phase(&tg.state);
    rb_advance_phase(&tg.state);
    // 
    // // Ability fires → choose self or opponent
    test_has_pending_choice(&tg);
    // // inlined helper choose_self
    // 
    test_has_pending_choice(&tg);
    // TODO assert_eq (unresolved): assert_eq!( game.pending_choice_type().as_deref(), Some("SelectTarget"), "expected SelectTarget self_or_opponent prompt" );
    rb_resume_with_choice(&tg.state, 0);
    // 
    // 
    // // Q85: After choose self, deck has 1 card (need 2). Take the 1 and show
    // // a skip-able selection choice rather than failing silently.
    test_has_pending_choice(&tg);
    // 
}

