// test_modules/abilities/simple/fuyumari_test.rs::fuyumari_q95_player_chooses_card_from_discard
static void gen_fuyumari_q95_player_chooses_card_from_discard(void){
    // 
    // db loaded via rb_load
    TestGame tg; test_game_new(&tg);
    // 
    int fuyumari = test_id(&tg, "PL!SP-pb1-011-R");
    int liella_member = test_id(&tg, "PL!SP-sd1-006-SD");
    int other_member = test_id(&tg, "PL!SP-sd1-008-SD");
    // 
    test_add_to_hand(&tg, fuyumari);
    tg.state.p[0].stage[0] = liella_member;
    test_add_to_discard(&tg, other_member);
    test_add_to_discard(&tg, liella_member);
    test_give_energy(&tg, 13);
    // 
    int discard_before = tg.state.p[0].discard.n;
    // 
    tg.state.p[0].stage[1] = -1;
    test_play_to_stage(&tg, fuyumari, 1);
    // 
    // // 1. Optional-cost gate: pay or skip (「〜してもよい」).
    // TODO assert: assert!( answer_stage_cost_gate(&mut game, true), "optional stage cost must present a pay/skip gate" );
    // // 2. Cost target selection: exactly one Liella! member on stage → the
    // // engine auto-applies it with NO prompt (single-candidate auto-resolve).
    // // 3. Effect: the very next ask is the re-deploy choice from the waitroom
    // // (SelectCard zone=discard count=1 allow_skip=false).
    test_has_pending_choice(&tg);
    // TODO assert_eq (unresolved): assert_eq!( game.pending_choice_type().as_deref(), Some("SelectCard"), "expected SelectCard (zone=discard, member_card) for the re-deploy choice" );
    rb_resume_with_choice(&tg.state, 0);
    test_has_pending_choice(&tg);
    // 
    CHECK_EQ(tg.state.p[0].stage[0], other_member, "fuyumari_q95_player_chooses_card_from_discard");
    CHECK_EQ(tg.state.p[0].stage[1], fuyumari, "fuyumari_q95_player_chooses_card_from_discard");
    CHECK(tg.state.p[0].discard.n, "fuyumari_q95_player_chooses_card_from_discard");
    // 
}

// test_modules/abilities/simple/fuyumari_test.rs::fuyumari_edge_no_valid_cost_target
static void gen_fuyumari_edge_no_valid_cost_target(void){
    // 
    // db loaded via rb_load
    TestGame tg; test_game_new(&tg);
    // 
    int fuyumari = test_id(&tg, "PL!SP-pb1-011-R");
    int filler = test_id(&tg, "PL!-sd1-010-SD");
    // 
    test_add_to_hand(&tg, fuyumari);
    test_add_to_hand(&tg, filler);
    tg.state.p[0].stage[0] = filler;
    test_give_energy(&tg, 13);
    // 
    tg.state.p[0].stage[1] = -1;
    test_play_to_stage(&tg, fuyumari, 1);
    // 
    // // Observed: zero valid candidates (non-Liella! filler excluded) → the
    // // optional cost auto-skips silently (KANAN_DEBUG cost_was_skipped=true);
    // // no prompt of any kind is presented, so the filler can never be offered.
    test_has_pending_choice(&tg);
    // 
    CHECK_EQ(tg.state.p[0].stage[0], filler, "fuyumari_edge_no_valid_cost_target");
    CHECK((!test_zone_has_id(&tg, 0, "discard", filler)), "fuyumari_edge_no_valid_cost_target");
    CHECK_EQ(tg.state.p[0].stage[1], fuyumari, "fuyumari_edge_no_valid_cost_target");
    // 
}

