// test_modules/jidou/complex/trigger_scope_test.rs::s2_pb1_006_opponent_drag_arms_per_move
static void gen_s2_pb1_006_opponent_drag_arms_per_move(void){
    // 
    // db loaded via rb_load
    TestGame tg; test_game_new(&tg);
    // 
    // // P1: the S2 watcher staged at RIGHT.
    int member = test_id(&tg, "PL!SP-pb1-006-R");
    // TODO set_active_side: game.set_active_side(Side::P1); // pin the acting seat explicitly
    test_give_energy(&tg, 9);
    test_add_to_hand(&tg, member);
    tg.state.p[0].stage[0] = -1;
    tg.state.p[0].stage[1] = -1;
    tg.state.p[0].stage[2] = member;
    test_play_to_stage(&tg, member, 2);
    // TODO: scan_autos_both(&mut game);
    CHECK_EQ(rb_mods_get_blade(&tg.state.mods, member), 2, "s2_pb1_006_opponent_drag_arms_per_move");
    // 
    // // P2 board: all-みらくらぱーく！ gate for the mover.
    int mirakura_a = test_id(&tg, "PL!HS-bp1-005-PR");
    int mover1 = test_id(&tg, "PL!HS-pb1-014-R");
    tg.state.p[1].stage[0] = mirakura_a;
    tg.state.p[1].stage[1] = -1;
    tg.state.p[1].stage[2] = -1;
    // TODO: game.add_to_hand_for(Side::P2, mover1);
    // TODO: game.give_energy_for(Side::P2, 9);
    // 
    // // DRAG #1: mover1 debuts at P2 center (faces P1 center) — the watcher is
    // // pulled right -> center. Distinct movement_event_counter => arms again.
    test_play_to_stage(&tg, mover1, 1);
    // action result consumed: .expect("p2 debut of mover1");
    while (test_has_pending_choice(&tg)) rb_resume_with_choice(&tg.state, 0);
    // TODO: answer_choice(&mut game, 0);
    // TODO: }
    // TODO: scan_autos_both(&mut game);
    // 
    CHECK_EQ(tg.state.p[0].stage[1], member, "s2_pb1_006_opponent_drag_arms_per_move");
    CHECK_EQ(rb_mods_get_blade(&tg.state.mods, member), 4, "s2_pb1_006_opponent_drag_arms_per_move");
    // 
    // // NOTE: multi-drag sequences within one turn are deliberately NOT pinned
    // // here — blind index answers to the facing-area prompt can select
    // // degenerate destinations (EPCWD source==target NOOP). Per-move arming is
    // // covered by opp_cause_fired_keys unit semantics; extend with a scripted
    // // two-mover scenario only alongside real UI-flow captures.
    // 
}

