// test_modules/batches/untested_secondary_abilities_test.rs::fuyuko_bpb5011_position_constants_are_mutually_exclusive
static void gen_fuyuko_bpb5011_position_constants_are_mutually_exclusive(void){
    // 
    // db loaded via rb_load
    TestGame tg; test_game_new(&tg);
    int fuyuko = test_id(&tg, "PL!SP-bp5-011-R");
    // 
    tg.state.p[0].stage[0] = fuyuko;
    test_recalc(&tg);
    CHECK_EQ(rb_mods_get_heart(&tg.state.mods, fuyuko, 2), 3, "fuyuko_bpb5011_position_constants_are_mutually_exclusive");
    CHECK_EQ(rb_mods_get_heart(&tg.state.mods, fuyuko, 3), 0, "fuyuko_bpb5011_position_constants_are_mutually_exclusive");
    CHECK_EQ(rb_mods_get_heart(&tg.state.mods, fuyuko, 5), 0, "fuyuko_bpb5011_position_constants_are_mutually_exclusive");
    // 
    tg.state.p[0].stage[0] = -1;
    tg.state.p[0].stage[1] = fuyuko;
    test_recalc(&tg);
    CHECK_EQ(rb_mods_get_heart(&tg.state.mods, fuyuko, 3), 3, "fuyuko_bpb5011_position_constants_are_mutually_exclusive");
    CHECK_EQ(rb_mods_get_heart(&tg.state.mods, fuyuko, 2), 0, "fuyuko_bpb5011_position_constants_are_mutually_exclusive");
    // 
    tg.state.p[0].stage[1] = -1;
    tg.state.p[0].stage[2] = fuyuko;
    test_recalc(&tg);
    CHECK_EQ(rb_mods_get_heart(&tg.state.mods, fuyuko, 5), 3, "fuyuko_bpb5011_position_constants_are_mutually_exclusive");
    CHECK_EQ(rb_mods_get_heart(&tg.state.mods, fuyuko, 3), 0, "fuyuko_bpb5011_position_constants_are_mutually_exclusive");
    // 
}

// test_modules/batches/untested_secondary_abilities_test.rs::ruby_bp6009_blades_equal_success_pile_difference
static void gen_ruby_bp6009_blades_equal_success_pile_difference(void){
    // 
    // db loaded via rb_load
    TestGame tg; test_game_new(&tg);
    int ruby = test_id(&tg, "PL!S-bp6-009-R＋");
    int live = test_id(&tg, "PL!-sd1-019-SD");
    // 
    tg.state.p[0].stage[1] = ruby;
    // 
    // // Opponent ahead by 3 → 3 blades.
    test_add_to_live(&tg, live);
    test_add_to_live(&tg, live);
    test_add_to_live(&tg, live);
    test_recalc(&tg);
    CHECK_EQ(rb_mods_get_blade(&tg.state.mods, ruby), 3, "ruby_bp6009_blades_equal_success_pile_difference");
    // 
    // // I take two successes → diff shrinks to 1.
    test_add_to_live(&tg, live);
    test_add_to_live(&tg, live);
    test_recalc(&tg);
    CHECK_EQ(rb_mods_get_blade(&tg.state.mods, ruby), 1, "ruby_bp6009_blades_equal_success_pile_difference");
    // 
    // // Caught up → condition (strictly more) fails → zero.
    test_add_to_live(&tg, live);
    test_recalc(&tg);
    CHECK_EQ(rb_mods_get_blade(&tg.state.mods, ruby), 0, "ruby_bp6009_blades_equal_success_pile_difference");
    // 
}

