    // 
    int crossroads = test_id(&tg, "PL!-bp6-024-L");
    int muse_live = test_id(&tg, "PL!-bp3-019-L");
    // 
    // // Put Crossroads in live_card_zone as if it was set during live card set
    test_add_to_live(&tg, crossroads);
    // // Put a μ's live card in discard
    // TODO: game.add_to_discard(muse_live);
    // 
    // // Simulate a won performance with 1 card: triggers replacement logic
    // TODO: TurnEngine::move_live_to_success_and_handle_wins(
    // TODO: &mut game.state,
    // TODO: true,  // player1 won
    // TODO: false, // player2 lost
    // TODO: );
    // 
    // // Should now have a pending SelectCard choice for the replacement
    test_has_pending_choice(&tg);
    // 
    // // Verify the choice identity metadata is correctly set (the bug fix)
    // TODO: game.assert_choice_identity(crossroads, "錯覚CROSSROADS", "p1");
