    int p2_hand_before = tg.state.p[1].hand.n;
    int p1_deck_before = tg.state.p[0].deck.n;
    // 
    // // 高坂穂乃果 (μ's, NOT Aqours) occupies center; Dia baton-touches over her.
    test_give_energy(&tg, 10);
