// test_modules/abilities/moderate/yoshiko_debut_test.rs::yoshiko_debit_stage_full_graceful
static void gen_yoshiko_debit_stage_full_graceful(void){
    // 
    // db loaded via rb_load
    TestGame tg; test_game_new(&tg);
    int yoshiko = test_id(&tg, "PL!S-bp2-006-R");
    int cost_2a = test_id(&tg, "PL!-sd1-002-SD");
    int cost_2b = test_id(&tg, "PL!-sd1-002-SD");
    int filler_m = test_id(&tg, "PL!-sd1-001-SD");
    int filler = test_id(&tg, "PL!-sd1-010-SD");
    // 
    tg.state.p[0].stage[0] = filler_m;
    tg.state.p[0].stage[1] = filler_m;
    tg.state.p[0].stage[2] = filler_m;
    test_add_to_discard(&tg, cost_2a);
    test_add_to_discard(&tg, cost_2b);
    test_add_to_hand(&tg, yoshiko);
    test_add_to_hand(&tg, filler);
    test_give_energy(&tg, 16);
    // 
    test_play_to_stage(&tg, yoshiko, 1);
    // 
    // // Hard chain: optional cost offered → both discard selections appear.
    // // A guard here would let the whole graceful scenario silently no-op.
    test_has_pending_choice(&tg);
    rb_resume_with_choice(&tg.state, 1);
    test_has_pending_choice(&tg);
    // TODO: game.select_waitroom_card_filtered(cost_2a);
    test_has_pending_choice(&tg);
    // TODO: game.select_waitroom_card_filtered(cost_2b);
    // 
    // // Stage full → cards stay in discard, NOT moved to hand
    // TODO assert: assert!( waitroom_contains(&game, cost_2a), "cost_2a should stay in discard when stage is full" );
    // TODO assert: assert!( waitroom_contains(&game, cost_2b), "cost_2b should stay in discard when stage is full" );
    CHECK((!test_zone_has_id(&tg, 0, "hand", cost_2a)), "yoshiko_debit_stage_full_graceful");
    // // Stage unchanged (yoshiko replaced center filler at play_to_stage)
    CHECK_EQ(tg.state.p[0].stage[1], yoshiko, "yoshiko_debit_stage_full_graceful");
    // // Only yoshiko's debut fired; placed cards couldn't appear
    // TODO assert_eq (unresolved): assert_eq!( game.state.player1.debut_count_this_turn, 1, "No extra debut triggers when stage is full" );
    // 
}

