// test_modules/jidou/complex/baton_touch_test.rs::opponent_baton_touch_discard_does_not_trigger
static void gen_opponent_baton_touch_discard_does_not_trigger(void){
    // 
    // db loaded via rb_load
    TestGame tg; test_game_new(&tg);
    // 
    // // 花帆 (PL!HS-sd1-001-SD) has: when baton-touched to waitroom by cost 10+ 蓮ノ空 → activate 2 energy
    int hanaho = test_id(&tg, "PL!HS-sd1-001-SD");
    int arriver = test_id(&tg, "PL!HS-sd1-006-SD");
    int filler = test_id(&tg, "PL!-sd1-010-SD");
    // 
    // // Put hanaho on Player 1's stage (she will be replaced by baton touch)
    tg.state.p[0].stage[1] = hanaho;
    // // Also put a copy of hanaho in Player 2's waitroom (as if P2 had their own replaced card)
    // // But the baton touch was performed by P1, so P2's hanaho should NOT trigger.
    int p2_hanaho = test_id(&tg, "PL!HS-sd1-001-SD");
    test_add_to_discard(&tg, p2_hanaho);
    // 
    // // Give energy to P1 for the baton touch cost
    test_give_energy(&tg, 25);
    // 
    test_add_to_hand(&tg, arriver);
    test_add_to_hand(&tg, filler);
    // 
    int p2_energy_before = tg.state.p[1].energy_active;
    // 
    // // Perform baton touch from P1's hand
    test_play_to_stage(&tg, arriver, 1);
    while (test_has_pending_choice(&tg)) rb_resume_with_choice(&tg.state, 0);
    rb_resume_with_choice(&tg.state, -1);
    // TODO: }
    // 
    // // P1's hanaho was replaced and should have triggered (activate 2 energy for P1)
    // // P2's hanaho should NOT have triggered even though it's in the waitroom,
    // // because the baton touch was performed by P1, not P2.
    // 
    int p2_energy_after = tg.state.p[1].energy_active;
    CHECK_EQ(p2_energy_after, p2_energy_before, "opponent_baton_touch_discard_does_not_trigger");
    // 
    // // Also verify baton touch is attributed correctly
    // TODO assert_eq (unresolved): assert_eq!( game.state.get_baton_touch_count("p1"), 1, "P1 has 1 baton touch" );
    // TODO assert_eq (unresolved): assert_eq!( game.state.get_baton_touch_count("p2"), 0, "P2 has 0 baton touches" );
    // 
}

