    test_add_to_deck(&tg, ball);
    test_add_to_deck(&tg, niji);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
