    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_give_energy(&tg, 20);
    // 
    // 
    // // Only きな子 on stage
    tg.state.p[0].stage[0] = -1;
    tg.state.p[0].stage[1] = kinako;
    tg.state.p[0].stage[2] = -1;
    // 
    // // Activate きな子 — should offer 2 positions (not center)
    test_activate_ability(&tg, kinako);
