// test_modules/batches/untested_abilities_test.rs::test_named_baton_touch_mia
static void gen_test_named_baton_touch_mia(void){
    // 
    // db loaded via rb_load
    TestGame tg; test_game_new(&tg);
    // 
    // // Setup cards
    int mia = test_id(&tg, "PL!N-pb1-022-P+");
    int shioriko = test_id(&tg, "PL!N-sd1-010-SD");
    int kasumi = test_id(&tg, "PL!N-sd1-002-SD");
    int filler = test_id(&tg, "PL!-sd1-010-SD");
    // 
    test_give_energy(&tg, 15);
    // 
    // // Scenario 1: Valid Baton Touch (Mia replaces Shioriko)
    test_add_to_stage(&tg, 1, shioriko);
    test_add_to_hand(&tg, mia);
    // 
    // // Add dummy cards so we can test the "draw 2 discard 1"
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    // 
    int _hand_before = 0;
    // 
    // // Play Mia over Shioriko
    test_play_to_stage(&tg, mia, 1);
    // 
    // // Hand size: Started at 1 (Mia). Played Mia -> 0. Ability triggers: Draw 2 -> 2. Discard 1 -> 1.
    // // If it's waiting for choice, we need to provide one.
    test_has_pending_choice(&tg);
    // 
    // // Hand should now have 2 cards (drawn from deck)
    CHECK_EQ(tg.state.p[0].hand.n, 2, "test_named_baton_touch_mia");
    // 
    // // Discard the first card
    rb_resume_with_choice(&tg.state, 0);
    // 
    // // Resolved! Hand should now be 1.
    CHECK_EQ(tg.state.p[0].hand.n, 1, "test_named_baton_touch_mia");
    // 
    // // Scenario 2: Invalid Baton Touch (Mia replaces Kasumi)
    int mia2 = test_id(&tg, "PL!N-pb1-022-P+");
    // 
    // // Clear center and put Kasumi there.
    // // Also remove Center card from deployed_this_turn (simulating it wasn't deployed this turn).
    int center_card = tg.state.p[0].stage[1];
    tg.state.p[0].stage[1] = -1;
    // TODO: game.state
    // TODO: .player1
    // TODO: .deployed_this_turn
    // TODO: .retain(|id| *id != center_card);
    test_add_to_stage(&tg, 1, kasumi);
    test_add_to_hand(&tg, mia2);
    // 
    // // Ensure deck has cards
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    // 
    // // Play Mia over Kasumi
    test_play_to_stage(&tg, mia2, 1);
    // 
    // // Ability should NOT trigger because Kasumi is not Shioriko. No pending choice!
    test_has_pending_choice(&tg);
    // 
}

