static void gen_jellyfish_q98_one_left_one_stays(void){
    // 
    // db loaded via rb_load
    TestGame tg; test_game_new(&tg);
    // 
    int jellyfish = test_id(&tg, "PL!SP-pb1-025-L");
    int chisato = test_id(&tg, "PL!SP-pb1-014-N");
    int natsumi = test_id(&tg, "PL!SP-pb1-009-R");
    // 
    // // inlined helper fill_decks
    // 
    int f = test_id(&tg, "PL!-sd1-010-SD");
    test_add_to_deck(&tg, f);
    f = test_id(&tg, "PL!-sd1-010-SD");
    test_add_to_deck(&tg, f);
    f = test_id(&tg, "PL!-sd1-010-SD");
    test_add_to_deck(&tg, f);
    f = test_id(&tg, "PL!-sd1-010-SD");
    test_add_to_deck(&tg, f);
    f = test_id(&tg, "PL!-sd1-010-SD");
    test_add_to_deck(&tg, f);
    f = test_id(&tg, "PL!-sd1-010-SD");
    test_add_to_deck(&tg, f);
    f = test_id(&tg, "PL!-sd1-010-SD");
    test_add_to_deck(&tg, f);
    f = test_id(&tg, "PL!-sd1-010-SD");
    test_add_to_deck(&tg, f);
    f = test_id(&tg, "PL!-sd1-010-SD");
    test_add_to_deck(&tg, f);
    f = test_id(&tg, "PL!-sd1-010-SD");
    test_add_to_deck(&tg, f);
    f = test_id(&tg, "PL!-sd1-010-SD");
    test_add_to_deck(&tg, f);
    f = test_id(&tg, "PL!-sd1-010-SD");
    test_add_to_deck(&tg, f);
    f = test_id(&tg, "PL!-sd1-010-SD");
    test_add_to_deck(&tg, f);
    f = test_id(&tg, "PL!-sd1-010-SD");
    test_add_to_deck(&tg, f);
    f = test_id(&tg, "PL!-sd1-010-SD");
    test_add_to_deck(&tg, f);
    f = test_id(&tg, "PL!-sd1-010-SD");
    test_add_to_deck(&tg, f);
    f = test_id(&tg, "PL!-sd1-010-SD");
    test_add_to_deck(&tg, f);
    f = test_id(&tg, "PL!-sd1-010-SD");
    test_add_to_deck(&tg, f);
    f = test_id(&tg, "PL!-sd1-010-SD");
    test_add_to_deck(&tg, f);
    f = test_id(&tg, "PL!-sd1-010-SD");
    test_add_to_deck(&tg, f);
    // 
    test_add_to_hand(&tg, jellyfish);
    test_give_energy(&tg, 20);
    // 
    // // Place both on stage
    tg.state.p[0].stage[0] = chisato;
    tg.state.p[0].stage[1] = natsumi;
    tg.state.p[0].stage[2] = -1;
    // 
    // // Remove Chisato (she left), Natsumi stays
    tg.state.p[0].stage[0] = -1;
    // 
    // // inlined helper advance_to_live_card_set_p1
    // 
    CHECK_EQ_STR(rb_phase_name(tg.state.phase), "Main", "jellyfish_q98_one_left_one_stays");
    rb_advance_phase(&tg.state);
    CHECK_EQ_STR(rb_phase_name(tg.state.phase), "Active", "jellyfish_q98_one_left_one_stays");
    rb_advance_phase(&tg.state);
    CHECK_EQ_STR(rb_phase_name(tg.state.phase), "Energy", "jellyfish_q98_one_left_one_stays");
    rb_advance_phase(&tg.state);
    CHECK_EQ_STR(rb_phase_name(tg.state.phase), "Draw", "jellyfish_q98_one_left_one_stays");
    rb_advance_phase(&tg.state);
    CHECK_EQ_STR(rb_phase_name(tg.state.phase), "Main", "jellyfish_q98_one_left_one_stays");
    rb_advance_phase(&tg.state);
    CHECK(strstr(rb_phase_name(tg.state.phase), "LiveCardSet") != NULL, "jellyfish_q98_one_left_one_stays");
    // 
    // 
    // // Re-insert appeared tracking AFTER phase advance (it may be cleared during passes)
    // TODO: game.state.cards_appeared_this_turn.push(natsumi);
    // 
    test_set_live_card(&tg, 0, jellyfish);
    // // inlined helper advance_to_live_start
    // 
    rb_advance_phase(&tg.state);
    rb_advance_phase(&tg.state);
    // 
    // 
    // // Q98: Only Natsumi (5yncri5e!) is on stage → reduction = 1
    // // inlined helper check_heart_reduction
    // 
    // TODO: use rabuka_engine::card::HeartColor;
    int reduction = 0;
    // TODO: .state
    // TODO: .mods
    // TODO: .get_need_heart_modifier(jellyfish, HeartColor::Heart00);
    CHECK_EQ(reduction, -1, "jellyfish_q98_one_left_one_stays");
    // 
    // 
}

