    rb_advance_phase(&tg.state);
    rb_advance_phase(&tg.state);
    rb_advance_phase(&tg.state);
    rb_advance_phase(&tg.state);
    rb_advance_phase(&tg.state);
    rb_advance_phase(&tg.state);
    rb_advance_phase(&tg.state);
    rb_advance_phase(&tg.state);
    rb_advance_phase(&tg.state);
    rb_advance_phase(&tg.state);
    // 
    // // After live end, blade should be 0
    int blade = rb_mods_get_blade(&tg.state.mods, maki);
    // TODO assert_eq (unresolved): assert_eq!( blade, 0, "Blade should expire after live end, got {}", blade );
