static void gen_serasu_edelnote_appear_triggers_opponent_wait(void){
    // 
    // db loaded via rb_load
    TestGame tg; test_game_new(&tg);
    // 
    int serasu = test_id(&tg, "PL!HS-bp6-007-R");
    int edelnote_member = test_id(&tg, "PL!HS-PR-022-PR");
    int p2_member_a = test_id(&tg, "PL!-sd1-010-SD");
    int p2_member_b = test_id(&tg, "PL!-sd1-013-SD");
    int filler = test_id(&tg, "PL!-sd1-013-SD");
    // 
    // // Serasu already on stage
    tg.state.p[0].stage[1] = serasu;
    // // Opponent has 2 active members → forces a choice (2 > count=1)
    tg.state.p[1].stage[0] = p2_member_a;
    tg.state.p[1].stage[1] = p2_member_b;
    tg.state.p[1].stage[2] = -1;
    // // EdelNote member in hand to play
    test_add_to_hand(&tg, edelnote_member);
    test_add_to_hand(&tg, filler);
    test_give_energy(&tg, 10);
    // 
    // // Play EdelNote member to stage → triggers Serasu's auto ability
    test_play_to_stage(&tg, edelnote_member, 0);
    // 
    // // Auto ability fires: opponent chooses which of their members to wait
    test_has_pending_choice(&tg);
    int entry = 0;
    // TODO assert_eq (unresolved): assert_eq!( entry.as_ref().and_then(|e| e.choice_player_id.as_deref()), Some("p2"), "Wait-member choice should be routed to opponent" );
    while (test_has_pending_choice(&tg)) rb_resume_with_choice(&tg.state, 0);
    rb_resume_with_choice(&tg.state, 0);
    // TODO: }
    // 
    // // Verify: waiting does not remove members from the stage — BOTH stay.
    // TODO assert: assert!( game.state.player2.stage.stage.contains(&p2_member_a) && game.state.player2.stage.stage.contains(&p2_member_b), "Both opponent members should remain on stage (wait ≠ leave)" );
    // TODO assert_eq (unresolved): assert_eq!( game.state.mods.get_orientation_modifier(p2_member_a), Some("wait"), "p2_member_a should be in wait state (first member was waited)" );
    // 
}

