// test_modules/abilities/complex/hanayo_bp4_constant_test.rs::hanayo_bp4_baton_touch_uses_modified_cost
static void gen_hanayo_bp4_baton_touch_uses_modified_cost(void){
    // 
    // db loaded via rb_load
    TestGame tg; test_game_new(&tg);
    // 
    int hanayo = test_id(&tg, "PL!-bp4-008-R");
    int arriver = test_id(&tg, "PL!-sd1-001-SD");
    // 
    // // Place Hanayo on stage
    tg.state.p[0].stage[1] = hanayo;
    // 
    // // Add 2 score-3 live cards → total = 6, triggers +3 cost
    // TODO: add_score3_live(&mut game);
    // TODO: add_score3_live(&mut game);
    // 
    test_recalc(&tg);
    CHECK_EQ(rb_mods_get_cost(&tg.state.mods, hanayo), 3, "hanayo_bp4_baton_touch_uses_modified_cost");
    // 
    // // Give enough energy for either cost calculation
    // // Base-only: cost = 11 - 4 = 7 energy needed
    // // With mod:  cost = 11 - 7 = 4 energy needed
    // // Give 7 energy → base-only succeeds, with-mod also succeeds
    // // Give 4 energy → base-only FAILS, with-mod succeeds
    // // Let's give exactly 5 energy → with-mod passes (5 >= 4), base-only would fail (5 < 7)
    test_give_energy(&tg, 5);
    // 
    test_add_to_hand(&tg, arriver);
    test_play_to_stage(&tg, arriver, 1);
    while (test_has_pending_choice(&tg)) rb_resume_with_choice(&tg.state, 0);
    rb_resume_with_choice(&tg.state, -1);
    // TODO: }
    // 
    // // Should have succeeded: 5 - 4 = 1 energy remaining
    int remaining = tg.state.p[0].energy_active;
    CHECK_EQ(remaining, 1, "hanayo_bp4_baton_touch_uses_modified_cost");
    // 
}

