// test_modules/abilities/complex/special_color_test.rs::special_color_q195_set_blade_liella_at_center
static void gen_special_color_q195_set_blade_liella_at_center(void){
    // 
    // db loaded via rb_load
    TestGame tg; test_game_new(&tg);
    // 
    int special = test_id(&tg, "PL!SP-bp4-025-L");
    int liella = test_id(&tg, "PL!SP-bp1-001-R");
    int non_liella = test_id(&tg, "PL!-sd1-010-SD");
    // 
    tg.state.p[0].stage[0] = non_liella;
    tg.state.p[0].stage[1] = liella;
    tg.state.p[0].stage[2] = -1;
    test_add_to_hand(&tg, special);
    test_add_to_hand(&tg, non_liella);
    // // inlined helper fill_decks
    // 
    int filler = test_id(&tg, "PL!-sd1-010-SD");
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    // 
    // 
    // // inlined helper advance_to_live_card_set_p1
    // 
    rb_advance_phase(&tg.state);
    rb_advance_phase(&tg.state);
    rb_advance_phase(&tg.state);
    rb_advance_phase(&tg.state);
    rb_advance_phase(&tg.state);
    CHECK(strstr(rb_phase_name(tg.state.phase), "LiveCardSet") != NULL, "special_color_q195_set_blade_liella_at_center");
    // 
    test_set_live_card(&tg, 0, special);
    // // inlined helper advance_to_live_start
    // 
    rb_advance_phase(&tg.state);
    rb_advance_phase(&tg.state);
    // 
    // 
    CHECK_EQ(rb_mods_get_blade(&tg.state.mods, liella), 3, "special_color_q195_set_blade_liella_at_center");
    CHECK_EQ(rb_mods_get_blade(&tg.state.mods, non_liella), 0, "special_color_q195_set_blade_liella_at_center");
    // 
}

