// test_modules/jidou/complex/natsumi_bp5_test.rs::natsumi_pb2_020_q264_no_trigger_when_zero_cards_revealed
static void gen_natsumi_pb2_020_q264_no_trigger_when_zero_cards_revealed(void){
    // 
    // db loaded via rb_load
    TestGame tg; test_game_new(&tg);
    int natsumi = test_id(&tg, "PL!SP-pb2-020-R");
    int liella_live = test_id(&tg, "PL!SP-sd1-023-SD");
    int fill = test_id(&tg, "PL!-sd1-010-SD");
    // 
    tg.state.p[0].stage[1] = natsumi;
    test_add_to_hand(&tg, liella_live);
    test_add_to_deck(&tg, fill);
    test_add_to_deck(&tg, fill);
    test_add_to_deck(&tg, fill);
    test_add_to_deck(&tg, fill);
    test_add_to_deck(&tg, fill);
    test_add_to_deck(&tg, fill);
    test_add_to_deck(&tg, fill);
    test_add_to_deck(&tg, fill);
    test_add_to_deck(&tg, fill);
    test_add_to_deck(&tg, fill);
    test_give_energy(&tg, 5);
    // 
    // // Set natsumi to wait so total_blade=0 → yell reveals 0 cards
    rb_mods_set_orientation(&tg.state.mods, natsumi, "wait");
    // 
    // // Advance through LiveCardSet to performance phase
    rb_advance_phase(&tg.state);
    rb_advance_phase(&tg.state);
    rb_advance_phase(&tg.state);
    rb_advance_phase(&tg.state);
    rb_advance_phase(&tg.state);
    CHECK(strstr(rb_phase_name(tg.state.phase), "LiveCardSet") != NULL, "natsumi_pb2_020_q264_no_trigger_when_zero_cards_revealed");
    test_set_live_card(&tg, 0, liella_live);
    rb_advance_phase(&tg.state);
    rb_advance_phase(&tg.state);
    rb_advance_phase(&tg.state);
    // 
    // // Q264: 0 cards revealed → condition not met → ability should NOT trigger.
    // // Strong form: the live card must NOT be in the discard; it stays where
    // // the flow left it (hand or live zone).
    CHECK((!test_zone_has_id(&tg, 0, "discard", liella_live)), "natsumi_pb2_020_q264_no_trigger_when_zero_cards_revealed");
    CHECK(test_zone_has_id(&tg, 0, "hand", liella_live), "natsumi_pb2_020_q264_no_trigger_when_zero_cards_revealed");
    // 
}

