    test_add_to_hand(&tg, reveal_b);
    test_add_to_discard(&tg, target_live);
    test_give_energy(&tg, 2);
    // 
    test_activate_ability(&tg, hino);
    // 
    // // First choice: select which live card to reveal from hand (2 > count=1)
    // // Choose index 0 (reveal_a)
    test_has_pending_choice(&tg);
    rb_resume_with_choice(&tg.state, 0);
