    int live = test_id(&tg, "PL!-sd1-010-SD");
    int filler = test_id(&tg, "PL!-sd1-010-SD");
    // 
    // // Stage: joint in center
    tg.state.p[0].stage[1] = joint;
    // // Hand: 3 matching names (joint self + ayumu + kanon) to pay cost
    test_add_to_hand(&tg, joint);
    test_add_to_hand(&tg, ayumu);
    test_add_to_hand(&tg, kanon);
    test_add_to_hand(&tg, live);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
