// test_modules/batches/untested_abilities_batch8_test.rs::seras_pb1015_loses_three_blade_when_alone
static void gen_seras_pb1015_loses_three_blade_when_alone(void){
    // 
    // db loaded via rb_load
    TestGame tg; test_game_new(&tg);
    // 
    int seras = test_id(&tg, "PL!HS-pb1-015-R");
    // action result consumed: assert_eq!(game.db.get_card(seras).unwrap().blade, 5);
    test_add_to_stage(&tg, 1, seras);
    // 
    // // Alone → −3 blade modifier.
    test_recalc(&tg);
    CHECK_EQ(rb_mods_get_blade(&tg.state.mods, seras), -3, "seras_pb1015_loses_three_blade_when_alone");
    // 
    // // A friend arrives → loss stops.
    // TODO: game.add_to_stage(MemberArea::LeftSide, test_id(&tg, "PL!-sd1-010-SD"));
    test_recalc(&tg);
    CHECK_EQ(rb_mods_get_blade(&tg.state.mods, seras), 0, "seras_pb1015_loses_three_blade_when_alone");
    // 
    // // Friend leaves → loss returns.
    tg.state.p[0].stage[0] = -1;
    test_recalc(&tg);
    CHECK_EQ(rb_mods_get_blade(&tg.state.mods, seras), -3, "seras_pb1015_loses_three_blade_when_alone");
    // 
}

