// test_modules/jidou/complex/ll_bp7_001_triple_member_test.rs::triple_many_duplicates_still_finds_assignment
static void gen_triple_many_duplicates_still_finds_assignment(void){
    // 
    // db loaded via rb_load
    TestGame tg; test_game_new(&tg);
    int triple_play = test_id(&tg, "LL-bp7-001-R＋");
    int triple_fodder = test_id(&tg, "LL-bp7-001-R＋");
    int hanamaru2 = test_id(&tg, "PL!S-bp2-007-R＋");
    int hanamaru3 = test_id(&tg, "PL!S-bp3-016-N");
    int setsuna = test_id(&tg, "PL!N-PR-009-PR");
    int chisato = test_id(&tg, "PL!SP-pb1-014-PR");
    // // Hand: triple_play, triple_fodder, hanamaru2, hanamaru3, setsuna, chisato
    // // Fodder needs 3 distinct: could use hanamaru2+setsuna+chisato, ignoring extras
    test_add_to_hand(&tg, triple_play);
    test_add_to_hand(&tg, triple_fodder);
    test_add_to_hand(&tg, hanamaru2);
    test_add_to_hand(&tg, hanamaru3);
    test_add_to_hand(&tg, setsuna);
    test_add_to_hand(&tg, chisato);
    test_give_energy(&tg, 10);
    test_play_to_stage(&tg, triple_play, 1);
    // TODO assert: assert!(answer_play_choice(&mut game, true));
    // TODO assert: assert!(game.state.player1.stage.stage.contains(&triple_play));
    CHECK_EQ(tg.state.p[0].discard.n, 3, "triple_many_duplicates_still_finds_assignment");
    // // triple_fodder should stay (not needed) OR be one of the three – either is valid, but distinctness holds
    int hand_len = tg.state.p[0].hand.n;
    CHECK_EQ(hand_len, 2, "triple_many_duplicates_still_finds_assignment");
    // 
}

