// test_modules/abilities/complex/ability_engine_fixes_test.rs::wakana_008_debut_move_to_occupied_area
static void gen_wakana_008_debut_move_to_occupied_area(void){
    // 
    // db loaded via rb_load
    TestGame tg; test_game_new(&tg);
    // 
    int wakana = test_id(&tg, "PL!SP-pb1-008-R");
    int occupant = test_id(&tg, "PL!-sd1-010-SD");
    int filler = test_id(&tg, "PL!-sd1-010-SD");
    // 
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_hand(&tg, wakana);
    test_give_energy(&tg, 15);
    // 
    // // Occupant at Right, Center empty for debut
    tg.state.p[0].stage[0] = -1;
    tg.state.p[0].stage[1] = -1;
    tg.state.p[0].stage[2] = occupant;
    // 
    test_play_to_stage(&tg, wakana, 1);
    // 
    // // Draw happened
    // // Area select choice → pick Right
    test_has_pending_choice(&tg);
    // 
    // // Options should exclude Center (current), include Left and Right
    // // Options: ["left", "right"] → option 1 = "right"
    rb_resume_with_choice(&tg.state, 1);
    // 
    // // After position_change (swap): occupant goes to Center, wakana goes to Right
    CHECK_EQ(tg.state.p[0].stage[0], -1, "wakana_008_debut_move_to_occupied_area");
    CHECK_EQ(tg.state.p[0].stage[1], occupant, "wakana_008_debut_move_to_occupied_area");
    CHECK_EQ(tg.state.p[0].stage[2], wakana, "wakana_008_debut_move_to_occupied_area");
    // 
    // TODO assert: assert!( game.state.ability_queue.is_waiting_for_choice().is_none(), "No choice should remain" );
    // 
}

