// test_modules/integration/gameplay_test.rs::ai_screeam_answer_both_discard
static void gen_ai_screeam_answer_both_discard(void){
    // 
    // db loaded via rb_load
    TestGame tg; test_game_new(&tg);
    int fill = test_id(&tg, "PL!-sd1-010-SD");
    test_add_to_deck(&tg, fill);
    test_add_to_deck(&tg, fill);
    test_add_to_deck(&tg, fill);
    test_add_to_deck(&tg, fill);
    test_add_to_deck(&tg, fill);
    test_add_to_deck(&tg, fill);
    test_add_to_deck(&tg, fill);
    test_add_to_deck(&tg, fill);
    test_add_to_deck(&tg, fill);
    test_add_to_deck(&tg, fill);
    test_add_to_deck(&tg, fill);
    test_add_to_deck(&tg, fill);
    test_add_to_deck(&tg, fill);
    test_add_to_deck(&tg, fill);
    test_add_to_deck(&tg, fill);
    test_add_to_deck(&tg, fill);
    test_add_to_deck(&tg, fill);
    test_add_to_deck(&tg, fill);
    test_add_to_deck(&tg, fill);
    test_add_to_deck(&tg, fill);
    // 
    int screeam = test_id(&tg, "LL-PR-004-PR");
    int filler_a = test_id(&tg, "PL!-sd1-010-SD");
    int filler_b = test_id(&tg, "PL!-sd1-013-SD");
    // 
    // // Card in hand. Both players get filler cards for discard.
    test_add_to_hand(&tg, screeam);
    test_add_to_hand(&tg, filler_a);
    test_add_to_hand(&tg, filler_b);
    // 
    int _p1_hand_before = tg.state.p[0].hand.n;
    int _p2_hand_before = tg.state.p[1].hand.n;
    // 
    // // Advance to LiveCardSetFirstAttacker
    // // inlined helper advance_to_live_card_set_p1
    // 
    CHECK_EQ_STR(rb_phase_name(tg.state.phase), "Main", "ai_screeam_answer_both_discard");
    rb_advance_phase(&tg.state);
    CHECK_EQ_STR(rb_phase_name(tg.state.phase), "Active", "ai_screeam_answer_both_discard");
    rb_advance_phase(&tg.state);
    CHECK_EQ_STR(rb_phase_name(tg.state.phase), "Energy", "ai_screeam_answer_both_discard");
    rb_advance_phase(&tg.state);
    CHECK_EQ_STR(rb_phase_name(tg.state.phase), "Draw", "ai_screeam_answer_both_discard");
    rb_advance_phase(&tg.state);
    CHECK_EQ_STR(rb_phase_name(tg.state.phase), "Main", "ai_screeam_answer_both_discard");
    rb_advance_phase(&tg.state);
    CHECK(strstr(rb_phase_name(tg.state.phase), "LiveCardSet") != NULL, "ai_screeam_answer_both_discard");
    // 
    CHECK(strstr(rb_phase_name(tg.state.phase), "LiveCardSet") != NULL, "ai_screeam_answer_both_discard");
    // 
    // // Set the live card — triggers ライブ開始時 abilities
    test_set_live_card(&tg, 0, screeam);
    // // inlined helper advance_to_live_start
    // 
    rb_advance_phase(&tg.state);
    rb_advance_phase(&tg.state);
    // 
    // 
    // // The ability fires and creates a "choice" prompt
    test_has_pending_choice(&tg);
    // 
    // // Verify choice_player_id is set to opponent
    int entry = 0;
    // TODO: .state
    // TODO: .ability_queue
    // TODO: .current_entry()
    // action result consumed: .expect("Queue should have an entry");
    // TODO assert_eq (unresolved): assert_eq!( entry.choice_player_id.as_deref(), Some("p2"), "Choice player should be p2 (opponent decides flavor)" );
    // 
    // // Option 0: mint/flavor/cookie → both discard 1 from hand
    // // P1 flow: start 2 (screeam + filler_a), P2 active during passes so no draws,
    // //   -1 set live, +1 live replacement, -1 discard = 1
    // // P2 flow: start 1 (filler_b), +1 draw (DrawPhaseP2Turn), -1 discard = 1
    rb_resume_with_choice(&tg.state, 0);
    // 
    // // "both" → effect targets P1 then P2; P2 also gets a discard choice
    test_has_pending_choice(&tg);
    // // Verify choice_player_id is "p1" — P1 chooses their own discard
    entry = 0;
    // TODO: .state
    // TODO: .ability_queue
    // TODO: .current_entry()
    // action result consumed: .expect("Queue should have an entry");
    // TODO assert_eq (unresolved): assert_eq!( entry.choice_player_id.as_deref(), Some("p1"), "P1's discard choice should have choice_player_id=p1" );
    // // P1 discards card from hand
    rb_resume_with_choice(&tg.state, 0);
    // // Now P2 gets a discard choice
    test_has_pending_choice(&tg);
    // // Verify choice_player_id is "p2" — P2 chooses their own discard
    entry = 0;
    // TODO: .state
    // TODO: .ability_queue
    // TODO: .current_entry()
    // action result consumed: .expect("Queue should have an entry");
    // TODO assert_eq (unresolved): assert_eq!( entry.choice_player_id.as_deref(), Some("p2"), "P2's discard choice should have choice_player_id=p2" );
    rb_resume_with_choice(&tg.state, 0);
    // 
    CHECK_EQ(tg.state.p[0].hand.n, 1, "ai_screeam_answer_both_discard");
    CHECK_EQ(tg.state.p[1].hand.n, 1, "ai_screeam_answer_both_discard");
    // 
}

