// test_modules/integration/gameplay_test.rs::distortion_basic_energy_refresh_with_catchu
static void gen_distortion_basic_energy_refresh_with_catchu(void){
    // 
    // db loaded via rb_load
    TestGame tg; test_game_new(&tg);
    // 
    int distortion = test_id(&tg, "PL!SP-pb1-023-L");
    int filler = test_id(&tg, "PL!-sd1-010-SD");
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    int catchu_a = test_id(&tg, "PL!SP-sd1-001-SD");
    int catchu_b = test_id(&tg, "PL!SP-sd1-004-SD");
    int energy_id = test_id(&tg, "LL-E-001-SD");
    // 
    // // Card in hand
    test_add_to_hand(&tg, distortion);
    test_add_to_hand(&tg, filler);
    // 
    // // Two CatChu! members on stage with DIFFERENT names (condition met)
    tg.state.p[0].stage[0] = catchu_a;
    tg.state.p[0].stage[2] = catchu_b;
    // 
    // // Give 3 active + 4 wait energy (= 7 total, 4 wait)
    test_give_energy(&tg, 3);
    test_add_to_discard(&tg, energy_id);
    test_add_to_discard(&tg, energy_id);
    test_add_to_discard(&tg, energy_id);
    test_add_to_discard(&tg, energy_id);
    CHECK_EQ(tg.state.p[0].energy.n, 7, "distortion_basic_energy_refresh_with_catchu");
    CHECK_EQ(tg.state.p[0].energy_active, 3, "distortion_basic_energy_refresh_with_catchu");
    CHECK_EQ(tg.state.p[0].energy_active, 3, "distortion_basic_energy_refresh_with_catchu");
    // 
    // // inlined helper advance_to_live_card_set_p1
    // 
    CHECK_EQ_STR(rb_phase_name(tg.state.phase), "Main", "distortion_basic_energy_refresh_with_catchu");
    rb_advance_phase(&tg.state);
    CHECK_EQ_STR(rb_phase_name(tg.state.phase), "Active", "distortion_basic_energy_refresh_with_catchu");
    rb_advance_phase(&tg.state);
    CHECK_EQ_STR(rb_phase_name(tg.state.phase), "Energy", "distortion_basic_energy_refresh_with_catchu");
    rb_advance_phase(&tg.state);
    CHECK_EQ_STR(rb_phase_name(tg.state.phase), "Draw", "distortion_basic_energy_refresh_with_catchu");
    rb_advance_phase(&tg.state);
    CHECK_EQ_STR(rb_phase_name(tg.state.phase), "Main", "distortion_basic_energy_refresh_with_catchu");
    rb_advance_phase(&tg.state);
    CHECK(strstr(rb_phase_name(tg.state.phase), "LiveCardSet") != NULL, "distortion_basic_energy_refresh_with_catchu");
    // 
    test_set_live_card(&tg, 0, distortion);
    // // inlined helper advance_to_live_start
    // 
    rb_advance_phase(&tg.state);
    rb_advance_phase(&tg.state);
    // 
    // 
    // // CatChu condition met → energy refresh should fire (up to 6, but only 4 wait)
    test_has_pending_choice(&tg);
    // 
    // // 4 wait cards should now be active
    CHECK_EQ(tg.state.p[0].energy_active, 7, "distortion_basic_energy_refresh_with_catchu");
    // 
    // // Now all energy active → score +1 should fire
    int live_card_id = 0;
    CHECK_EQ(rb_mods_get_score(&tg.state.mods, live_card_id), 1, "distortion_basic_energy_refresh_with_catchu");
    // 
}

