    rb_advance_phase(&tg.state);
    CHECK_EQ_STR(rb_phase_name(tg.state.phase), "Draw", "you_live_start_optional_cost_triggers");
    rb_advance_phase(&tg.state);
    CHECK_EQ_STR(rb_phase_name(tg.state.phase), "Main", "you_live_start_optional_cost_triggers");
    rb_advance_phase(&tg.state);
    CHECK(strstr(rb_phase_name(tg.state.phase), "LiveCardSet") != NULL, "you_live_start_optional_cost_triggers");
