    rb_resume_with_choice(&tg.state, 0);
    rb_resume_with_choice(&tg.state, -1);
    // 
    // // Verify blade modifier was applied on the activating card
    int blade_mod = rb_mods_get_blade(&tg.state.mods, keke);
    // TODO assert: assert!( blade_mod > 0, "Blade should be gained on activating card after discarding named char (got {})", blade_mod );
