// test_modules/integration/gameplay_test.rs::energy_zone_capacity_handled
static void gen_energy_zone_capacity_handled(void){
    // 
    // db loaded via rb_load
    TestGame tg; test_game_new(&tg);
    // 
    // // Start at 0 energy
    CHECK_EQ(tg.state.p[0].energy.n, 0, "energy_zone_capacity_handled");
    CHECK_EQ(tg.state.p[0].energy_active, 0, "energy_zone_capacity_handled");
    // 
    // // Give maximum energy
    test_give_energy(&tg, 20);
    CHECK_EQ(tg.state.p[0].energy.n, 20, "energy_zone_capacity_handled");
    CHECK_EQ(tg.state.p[0].energy_active, 20, "energy_zone_capacity_handled");
    // 
    // // Spend energy (simulate paying a cost)
    test_spend_energy(&tg, 5);
    CHECK_EQ(tg.state.p[0].energy_active, 15, "energy_zone_capacity_handled");
    CHECK_EQ(tg.state.p[0].energy.n, 20, "energy_zone_capacity_handled");
    // 
    // // Spend all remaining
    test_spend_energy(&tg, 15);
    CHECK_EQ(tg.state.p[0].energy_active, 0, "energy_zone_capacity_handled");
    // 
    // // Try to spend below 0 (should not crash, saturating)
    test_spend_energy(&tg, 1);
    CHECK_EQ(tg.state.p[0].energy_active, 0, "energy_zone_capacity_handled");
    // 
}

// test_modules/integration/gameplay_test.rs::umi_pr014_appear_reveal_and_draw_when_no_live_card
static void gen_umi_pr014_appear_reveal_and_draw_when_no_live_card(void){
    // 
    // db loaded via rb_load
    TestGame tg; test_game_new(&tg);
    int umi = test_id(&tg, "PL!-PR-014-PR");
    int filler = test_id(&tg, "PL!-sd1-010-SD");
    // 
    // // Give P1 3 energy and Umi in hand, populate deck
    test_give_energy(&tg, 3);
    // clear
    test_add_to_hand(&tg, umi);
    // clear
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    int deck_before = tg.state.p[0].deck.n;
    // 
    // // Opponent has exactly 3 non-live cards in hand
    // clear
    test_add_to_hand(&tg, filler);
    test_add_to_hand(&tg, filler);
    test_add_to_hand(&tg, filler);
    // 
    // // Play Umi to stage (cost 2, 登場 trigger fires)
    tg.state.p[0].stage[0] = -1;
    tg.state.p[0].stage[1] = -1;
    tg.state.p[0].stage[2] = -1;
    test_play_to_stage(&tg, umi, 0);
    // 
    // // 登場 trigger: reveal 3 from opponent's hand → no live cards → draw 1.
    // // The reveal resolves automatically — no prompts.
    test_has_pending_choice(&tg);
    // 
    // // Umi cost is 2, we had 3 energy
    int energy_after = tg.state.p[0].energy_active;
    CHECK_EQ(energy_after, 1, "umi_pr014_appear_reveal_and_draw_when_no_live_card");
    // 
    // // P1 should have drawn 1 card (no live cards in opponent's revealed hand)
    // TODO assert_eq (unresolved): assert_eq!( game.state.player1.hand.len(), 1, "P1 should draw 1 card when no live card revealed" );
    // 
    // // Deck decreased by 1
    // TODO assert_eq (unresolved): assert_eq!( game.state.player1.main_deck.cards.len(), deck_before - 1, "Deck should have 1 less card" );
    // 
    // // Revealed cards should be in game state
    // TODO assert_eq (unresolved): assert_eq!( game.state.revealed_cards.len(), 3, "3 cards should be in revealed_cards" );
    // 
    // // Opponent hand still has 3 cards (reveal doesn't remove from hand)
    // TODO assert_eq (unresolved): assert_eq!( game.state.player2.hand.len(), 3, "P2 should still have 3 cards in hand (revealed, not removed)" );
    test_has_pending_choice(&tg);
    // 
}

