// test_modules/integration/gameplay_test.rs::hanamaru_score_icon_filter
static void gen_hanamaru_score_icon_filter(void){
    // 
    // db loaded via rb_load
    TestGame tg; test_game_new(&tg);
    int hanamaru = test_id(&tg, "PL!S-sd1-007-SD");
    int filler = test_id(&tg, "PL!-sd1-010-SD");
    // 
    // // Aqours live card WITH score icon → should be selectable
    int score_live = test_id(&tg, "PL!S-bp2-024-L");
    // // Aqours live card WITHOUT score icon → should NOT be selectable
    int no_score_live = test_id(&tg, "PL!S-bp2-026-L");
    // // Member card from same series → should NOT be selectable
    int member = test_id(&tg, "PL!S-bp2-015-PR");
    // 
    // // Hand: hanamaru + 2 cards to discard for cost
    test_add_to_hand(&tg, hanamaru);
    test_add_to_hand(&tg, filler);
    test_add_to_hand(&tg, filler);
    // 
    // // Discard: one score live, one non-score live, one member
    test_add_to_discard(&tg, score_live);
    test_add_to_discard(&tg, no_score_live);
    test_add_to_discard(&tg, member);
    // 
    test_give_energy(&tg, 15);
    // 
    // // Manually place hanamaru on stage
    tg.state.p[0].stage[0] = hanamaru;
    // TODO: game.state.player1.hand.cards.retain(|id| *id != hanamaru);
    // 
    // // Verify the card has the ability with card_property: has_score_icon
    // TODO: {
    // action result consumed: let card_data = game.state.card_database.get_card(hanamaru).unwrap();
    int has_ability = 0;
    // TODO: a.effect
    // TODO: .as_ref()
    // TODO: .is_some_and(|e| e.card_property_any() == Some("has_score_icon"))
    // TODO: });
    CHECK(has_ability, "hanamaru_score_icon_filter");
    // TODO: }
    // 
    // // Activate 起動 ability
    test_activate_ability(&tg, hanamaru);
    // 
    // // Cost: Select 2 cards from hand to discard
    // TODO assert_eq (unresolved): assert_eq!( game.pending_choice_type(), Some("SelectCard".to_string()), "Cost: select 2 cards from hand" );
    rb_resume_with_choice(&tg.state, 0);
    rb_resume_with_choice(&tg.state, 1);
    // 
    // // No pending choice — exactly 1 candidate matched (score_live), so auto-selected.
    test_has_pending_choice(&tg);
    // 
    // // Verify: score_live moved from waitroom to hand
    CHECK((!test_zone_has_id(&tg, 0, "discard", score_live)), "hanamaru_score_icon_filter");
    CHECK(test_zone_has_id(&tg, 0, "hand", score_live), "hanamaru_score_icon_filter");
    // 
    // // Verify: non-score live and member remain in discard
    CHECK(test_zone_has_id(&tg, 0, "discard", no_score_live), "hanamaru_score_icon_filter");
    CHECK(test_zone_has_id(&tg, 0, "discard", member), "hanamaru_score_icon_filter");
    // 
}

